/**
 * Default share image, generated by app/opengraph-image.tsx.
 *
 * A page that declares its own `openGraph` object replaces the parent's entirely, so it
 * loses the root og:image; without one, WhatsApp/Facebook pick an arbitrary image from
 * the page. Pages without their own opengraph-image file must list this explicitly.
 */
export const DEFAULT_OG_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: "Morel Technology - Laptops en República Dominicana",
};
